      "level": "apply",
      "question": "Compare $\\frac{3}{4}$ and $\\frac{2}{5}$ using cross multiplication. Which fraction is greater?",
      "options": [
        "$\\frac{3}{4}$",
        "$\\frac{2}{5}$",
        "They are equal"
      ],
      "correct_index": 0,
      "explanation": "To compare $\\frac{3}{4}$ and $\\frac{2}{5}$ using cross multiplication, we multiply the numerator of the first fraction by the denominator of the second fraction ($3 \\times 5 = 15$) and the numerator of the second fraction by the denominator of the first fraction ($2 \\times 4 = 8$). Since $15 > 8$, the first fraction $\\frac{3}{4}$ is greater.",
      "selected_because": "the lesson example comparing 3/4 and 2/5 using cross multiplication",
      "distractor_misconceptions": {
        "1": "compares numerators or denominators only",
        "2": "believes all fractions are equal or cannot be compared"
      },
      "option_feedback": {
        "correct": "Excellent! You correctly applied cross multiplication. The product $3 \\times 5 = 15$ for $\\frac{3}{4}$ is greater than $2 \\times 4 = 8$ for $\\frac{2}{5}$.",
        "wrong": {
          "1": "Remember, comparing fractions means finding out which one represents a larger part of a whole. Simply looking at numerators or denominators alone won't always tell you. Use cross multiplication as we learned for $\\frac{3}{4}$ and $\\frac{2}{5}$.",
          "2": "Fractions represent parts of a whole, and these parts can be different sizes. We learned methods like cross multiplication to find out if one fraction is greater, smaller, or equal to another."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "Compare $\\frac{3}{4}$ and $\\frac{2}{5}$ using cross multiplication.",
      "teaching_error": null
    },
